/* @lc app=leetcode id=4051 lang=kotlin */ class Solution { tailrec fun ad(b: IntArray, i: Int, d: Int): Unit { if (i < b.size) ad(b.also { it[i] += d }, i + (i and -i), d) } tailrec fun qc(b: IntArray, i: Int, a: Int = 0): Int { return if (i <= 0) a else qc(b, i - (i and -i), a + b[i]) } fun le(P: LongArray, sv: LongArray, x: Long): Long = IntArray(sv.size + 1).let { bit -> P.indices.sumOf { b -> (b - qc(bit, sv.binarySearch(P[b] - x).let { if (it < 0) -it - 1 else it })).toLong().also { ad(bit, sv.binarySearch(P[b]) + 1, 1) } } } fun distantSubarrays(nums: IntArray, goal: Int, k: Int): Long = nums.runningFold(0L) { a, b -> a + b }.toLongArray().let { P -> P.distinct().sorted().toLongArray().let { sv -> (nums.size.toLong() * (nums.size + 1) / 2).let { tot -> if (k == 0) tot else le(P, sv, goal.toLong() - k) + tot - le(P, sv, goal.toLong() + k - 1) } } } }